int main() {
    FILE *fp;
    long count = 0;
    fp = fopen("test.txt", "r");
    if (fp == NULL) return 1; // 增加打开失败的判断

    // 正确的循环方式：先读，再判断是否EOF
    while(fgetc(fp) != EOF) {
        count++;
    }

    printf("Char count: %ld\n", count);
    fclose(fp);
    return 0;
}
